-- Oracle
-- Datas
DROP TABLE user2tag CASCADE CONSTRAINT;
DROP TABLE note2touite CASCADE CONSTRAINT;
DROP TABLE tag2touite CASCADE CONSTRAINT;
DROP TABLE follow CASCADE CONSTRAINT;
DROP TABLE tag CASCADE CONSTRAINT;
DROP TABLE touite CASCADE CONSTRAINT;
DROP TABLE users CASCADE CONSTRAINT;

CREATE TABLE touite (
    -- le GENERATED BY ALWAYS AS IDENTITY pour remplacer le AUTO_INCREMENT
    id NUMBER(38) GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    content varchar2(235) NOT NULL,
    note NUMBER(5),
    image_description varchar2(235),
    image_path varchar2(256),
    posted_at DATE NOT NULL,
    users_id NUMBER(11) NOT NULL
);

CREATE TABLE users (
    -- le GENERATED ALWAYS AS IDENTITY pour remplacer le AUTO_INCREMENT
    id NUMBER(11) GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email varchar2(256) NOT NULL,
    passwd varchar2(256) NOT NULL,
    nom varchar2(100) NOT NULL,
    prenom varchar2(100) NOT NULL,
    counter_touite NUMBER(38) DEFAULT 0 NOT NULL
);

CREATE TABLE tag (
    -- le GENERATED ALWAYS AS IDENTITY pour remplacer le AUTO_INCREMENT
    id NUMBER(11) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    libelle varchar2(100) NOT NULL,
    description varchar2(256) NOT NULL
);

CREATE TABLE follow (
    follower_id NUMBER(11),
    followed_id NUMBER(11),
    PRIMARY KEY (follower_id, followed_id)
);

CREATE TABLE tag2touite (
    touite_id NUMBER(38),
    tag_id NUMBER(11),
    PRIMARY KEY (touite_id, tag_id)
);

CREATE TABLE note2touite (
    users_id NUMBER(11),
    touite_id NUMBER(38),
    -- -1 : négatif, 1 : POSITIF
    state NUMBER(1),
    PRIMARY KEY (users_id, touite_id)
);

CREATE TABLE user2tag (
    users_id NUMBER(11),
    tag_id NUMBER(11),
    PRIMARY KEY (users_id, tag_id)
);

-- Clés étrangères :
ALTER TABLE user2tag ADD FOREIGN KEY (users_id) REFERENCES users(id);
ALTER TABLE user2tag ADD FOREIGN KEY (tag_id) REFERENCES tag(id);
ALTER TABLE note2touite ADD FOREIGN KEY (users_id) REFERENCES users(id);
ALTER TABLE note2touite ADD FOREIGN KEY (touite_id) REFERENCES touite(id);
ALTER TABLE tag2touite ADD FOREIGN KEY (touite_id) REFERENCES touite(id);
ALTER TABLE tag2touite ADD FOREIGN KEY (tag_id) REFERENCES tag(id);
ALTER TABLE follow ADD FOREIGN KEY (follower_id) REFERENCES users(id);
ALTER TABLE follow ADD FOREIGN KEY (followed_id) REFERENCES users(id);
ALTER TABLE touite ADD FOREIGN KEY (users_id) REFERENCES users(id);

-- Contraintes :
ALTER TABLE users ADD CONSTRAINT uq_users_email UNIQUE (email);
ALTER TABLE tag ADD CONSTRAINT uq_tag_libelle UNIQUE (libelle);
ALTER TABLE users ADD CONSTRAINT chk_counter_touite_positiv CHECK (counter_touite >= 0);
ALTER TABLE follow ADD CONSTRAINT chk_no_self_follow CHECK (follower_id != followed_id);
ALTER TABLE note2touite ADD CONSTRAINT chk_note_bool CHECK (state IN (-1, 0, 1));

